import re, glob
sig_core = re.compile(r'dart test\b')
sig_flutter_test = re.compile(r'flutter test\b')
sig_build = re.compile(r'flutter build (apk|appbundle|ios|ipa|macos|web|aab)\b')
sig_fastlane = re.compile(r'fastlane android build_release')
for wf in sorted(glob.glob('.github/workflows/*.yml')):
    text = open(wf).read()
    # crude job split: lines starting with two spaces + name: 
    jobs = re.split(r'\n  (?=[a-z][a-z0-9-]+:\n)', text)
    for j in jobs:
        m = re.match(r'\s*([a-z][a-z0-9-]+):\n', j)
        if not m: continue
        name = m.group(1)
        hits = []
        if sig_core.search(j): hits.append('dart-test')
        if sig_flutter_test.search(j): hits.append('flutter-test')
        if sig_build.search(j): hits.append('flutter-build:' + ','.join(sorted(set(sig_build.findall(j)))))
        if sig_fastlane.search(j): hits.append('fastlane')
        if hits:
            nm = re.search(r'\n\s*name: (.+)', j)
            print(f"{wf.split('/')[-1]:26} {name:28} {nm.group(1).strip()[:44] if nm else '':44} {hits}")
EOF

