    m = re.match(r'\s*([a-z][a-z0-9_-]+):\n', j)
    if not m: continue
    name = m.group(1)
    body = j
    # strip full-line comments
    stripped = '\n'.join(l for l in body.splitlines() if not l.strip().startswith('#'))
    has_pubget = bool(re.search(r'\bdart pub get\b', stripped))
    uses_flutterpubget = 'flutter-pub-get' in stripped
    dart_test = bool(re.search(r'\bdart test\b', stripped))
    dart_run = bool(re.search(r'\bdart (run |bin/)', stripped))
    dart_compile = bool(re.search(r'\bdart compile\b', stripped))
    flutter_test = bool(re.search(r'\bflutter test\b', stripped))
    flutter_build = bool(re.search(r'\bflutter build (apk|appbundle|ios|ipa|macos)\b', stripped))
    flags = []
    if has_pubget: flags.append('dart-pub-get')
    if uses_flutterpubget: flags.append('uses-flutter-pub-get')
    if dart_test: flags.append('dart-test')
    if dart_run: flags.append('dart-run')
    if dart_compile: flags.append('dart-compile')
    if flutter_test: flags.append('flutter-test')
    if flutter_build: flags.append('flutter-build')
    if flags:
        print(f"{name:26} {flags}")
