```dart
const List<int> _k = [ ... 64 constants ... ];
String sha256Hex(List<int> bytes) {
 final h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
 final bitLen = bytes.length * 8;
 final padded = <int>[...bytes, 0x80];
 while (padded.length % 64 != 56) padded.add(0);
 for (var i = 7; i >= 0; i--) padded.add((bitLen >> (8 * i)) & 0xff);
 final w = List<int>.filled(64, 0);
 for (var chunk = 0; chunk < padded.length; chunk += 64) {
   for (var t = 0; t < 16; t++) {
     w[t] = (padded[chunk + 4*t] << 24) | (padded[chunk + 4*t+1] << 16) | (padded[chunk + 4*t+2] << 8) | padded[chunk + 4*t+3];
   }
   for (var t = 16; t < 64; t++) {
     final s0 = _rotr(w[t-15], 7) ^ _rotr(w[t-15], 18) ^ (w[t-15] >> 3);
     final s1 = _rotr(w[t-2], 17) ^ _rotr(w[t-2], 19) ^ (w[t-2] >> 10);
     w[t] = (w[t-16] + s0 + w[t-7] + s1) & 0xffffffff;
   }
   var a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],hh=h[7];
   for (var t = 0; t < 64; t++) {
     final S1 = _rotr(e,6) ^ _rotr(e,11) ^ _rotr(e,25);
     final ch = (e & f) ^ ((~e & 0xffffffff) & g);
     final temp1 = (hh + S1 + ch + _k[t] + w[t]) & 0xffffffff;
     final S0 = _rotr(a,2) ^ _rotr(a,13) ^ _rotr(a,22);
     final maj = (a & b) ^ (a & c) ^ (b & c);
     final temp2 = (S0 + maj) & 0xffffffff;
     hh=g; g=f; f=e; e=(d+temp1)&0xffffffff; d=c; c=b; b=a; a=(temp1+temp2)&0xffffffff;
   }
   h[0]=(h[0]+a)&0xffffffff; ... etc
 }
 return h.map((x) => x.toRadixString(16).padLeft(8,'0')).join();
}
int _rotr(int x, int n) => ((x >> n) | (x << (32-n))) & 0xffffffff;
``

