Future<File> downloadVerified({required Uri uri, required String expectedSha256, required File target, required int attempts, required int backoffBaseSeconds, required void Function(String) log}) async {
 target.parent.createSync(recursive: true);
 final tmp = File('${target.path}.tmp');
 Object? lastError;
 for (var attempt = 1; attempt <= attempts; attempt++) {
   try {
     tmp.parent.createSync(recursive: true);
     if (tmp.existsSync()) tmp.deleteSync();
     final client = HttpClient()..findProxy = HttpClient.findProxyFromEnvironment;
     final request = await client.getUrl(uri);
     request.headers.add('User-Agent', 'fa-ci sqlite3 native-assets prewarm (gh-2072)');
