   } catch (e) {
     lastError = e;
     log('attempt $attempt/$atempts failed: $e');
     if (tmp.existsSync()) { try { tmp.deleteSync(); } catch (_) {} }
     if (attempt < attempts) {
       final wait = backoffBaseSeconds * (1 << (attempt - 1));
       await Future<void>.delayed(Duration(seconds: wait));
     }
   }
 }
 throw PrewarmException('download failed after $atempts attempts: $lastError');
}
