python3 - <<'EOF'
import re

PREWARM = '      - uses: ./.github/actions/sqlite3-native-assets-prewarm\n'

def step_block_end(lines, start):
    """start = index of a line beginning a step ('      - ...'). Return the index
    of the LAST line of that step block (before the next same-indent '- ' line)."""
    indent = len(lines[start]) - len(lines[start].lstrip())
    end = start
    i = start + 1
    while i < len(lines):
        l = lines[i]
        if l.strip() and (len(l) - len(l.lstrip())) <= indent and l.strip().startswith('- '):
            break
        end = i
        i += 1
    return end

def find_anchor(lines, s, e):
    """Return the index of the line whose step should be followed by the prewarm,
    preferring: native-assets hook cache step > root dart pub get step > flutter-pub-get uses step."""
    pubget_named = pubget_run = cache_step = flutterpub = None
    for i in range(s, e):
        l = lines[i]
        if l.strip().startswith('- ') and 'Native-assets hook cache' in l:
            cache_step = i
        if l.strip().startswith('- run: dart pub get') and pubget_run is None:
            pubget_run = i
        if re.match(r'^      - name: dart pub get \(root\)', l) and pubget_named is None:
            pubget_named = i
        if './.github/actions/flutter-pub-get' in l and l.strip().startswith('uses:') and flutterpub is None:
            flutterpub = i - 1  # the '- name/- uses:' owner line may differ; uses: lines own their block from the '- ' line above only if shaped '- uses:'
    # flutter-pub-get steps here are shaped:
    #   - name: Install dependencies
    #     uses: ./.github/actions/flutter-pub-get
    # so the step start is the '- name' line above the uses: line.
    if flutterpub is not None:
        # walk back to the step owner
        j = flutterpub
        while j > s and not lines[j].strip().startswith('- '):
            j -= 1
        flutterpub = j
    for cand in (cache_step, pubget_run, pubget_named, flutterpub):
        if cand is not None:
            return cand
    return None

